/* Trzy liczby na kafelek i LISTA faktur na ekran pod nim: ile wisi, ile już jest
   w koszyku do przelewu, ile jest po terminie i — od teraz — co konkretnie.

   Zobowiązaniem jest faktura w statusie DO ZAPŁATY albo W KOSZYKU. INBOX
   i OTRZYMANY to etapy obiegu, nie zobowiązanie: dokument dopiero wpadł i nikt
   jeszcze nie potwierdził, że mamy go płacić. Statusy stoją w Configu, bo to
   decyzja o tym, co liczymy — nie szczegół implementacji.

   Dzień bierzemy w strefie Europe/Warsaw, a nie z UTC: o 23:30 naszego czasu
   UTC ma jeszcze wczoraj i faktura z terminem na dziś liczyłaby się jako
   przeterminowana o dobę za wcześnie. */
const cfg = $('⚙️ Config').first().json;
const dzis = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Warsaw' })
  .format(new Date());                       // sv-SE daje RRRR-MM-DD

const naListe = (t) => String(t || '').split(',')
  .map((x) => x.trim().toUpperCase()).filter(Boolean);
const liczone = naListe(cfg.statusyNiezaplacone);
const wKoszyku = naListe(cfg.statusKoszyk);

const wiersze = [];
for (const poz of $input.all()) {
  const b = poz.json;
  // Węzeł HTTP oddaje albo całą odpowiedź, albo same pozycje — bierzemy oba kształty.
  if (Array.isArray(b.items)) wiersze.push(...b.items);
  else if (b && b.id) wiersze.push(b);
}

const liczba = (t) => {
  const n = parseFloat(t);
  return Number.isFinite(n) ? n : 0;
};

/* Pozostało do zapłaty = kwota z faktury minus to, co już na nią poszło.
   Faktura w obcej walucie: skalujemy wartość w złotych tą samą proporcją,
   bo kursu w wierszu listy nie ma. Przy fakturach złotówkowych to tożsamość. */
const doZaplaty = (w) => {
  const due = liczba(w.amountDue);
  const reszta = due - liczba(w.paidAmount);
  if (reszta <= 0) return 0;
  if (!w.currency || w.currency === 'PLN' || due === 0) return reszta;
  return liczba(w.grossPln) * (reszta / due);
};

const grosze = (x) => Math.round(x * 100) / 100;
const pusta = () => ({ ile: 0, kwota: 0 });
const niezaplacone = pusta(), koszyk = pusta(), przeterminowane = pusta();
const faktury = [];
let pominiete = 0;

for (const w of wiersze) {
  const status = ((w.status && (w.status.name || w.status.shortCode)) || '').toUpperCase();
  if (liczone.indexOf(status) < 0) { pominiete++; continue; }

  const kwota = doZaplaty(w);
  if (kwota <= 0) continue;                  // pokryta w całości wyciągiem
  niezaplacone.ile++; niezaplacone.kwota += kwota;

  if (wKoszyku.indexOf(status) >= 0) { koszyk.ile++; koszyk.kwota += kwota; }
  // Bez terminu nie ma czego przekroczyć — taka faktura nie jest przeterminowana.
  if (w.dueDate && w.dueDate < dzis) {
    przeterminowane.ile++; przeterminowane.kwota += kwota;
  }

  /* Do zestawienia idzie tyle, ile się na nim czyta: komu, do kiedy, ile.
     `kwota` to brutto z faktury, bo o to pyta ekran; `doZaplaty` bywa mniejsze,
     gdy część pokrył już wyciąg, i wtedy Planner pokazuje obie. Numer KSeF
     w zastępstwie numeru własnego, bo po którymś z nich szuka się w CU 2.0. */
  faktury.push({
    dostawca: w.counterpartyName || '',
    numer: w.number || w.ksefNumber || '',
    termin: w.dueDate || null,
    kwota: grosze(liczba(w.grossPln) || liczba(w.amountDue)),
    doZaplaty: grosze(kwota),
    status: status,
  });
}

for (const g of [niezaplacone, koszyk, przeterminowane]) g.kwota = grosze(g.kwota);

/* `pominiete` nie idzie do Plannera — to liczba faktur w INBOX-ie i OTRZYMANYCH,
   przydatna w logu n8n, gdy ktoś zapyta, czemu kafelek pokazuje mniej, niż widać
   w CU 2.0. */
console.log('poza liczonymi statusami: ' + pominiete + ' z ' + wiersze.length
  + '; do wysłania: ' + faktury.length);
return [{ json: { firma: cfg.firma, niezaplacone, koszyk, przeterminowane, faktury } }];
